<?php
add_action('after_setup_theme', function(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',array('search-form'));register_nav_menus(array('primary'=>'Основное меню'));});
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('linguaspace',get_stylesheet_uri(),array(),'5.0');});
add_action('wp_head',function(){if(is_singular()){ $d=get_post_meta(get_queried_object_id(),'ls_description',true); if($d) echo '<meta name="description" content="'.esc_attr($d).'">'."\n";}});
add_action('admin_post_nopriv_ls_contact','ls_contact');add_action('admin_post_ls_contact','ls_contact');
function ls_text_length($value){return function_exists("mb_strlen") ? mb_strlen($value) : preg_match_all("/./us", $value);}
function ls_contact(){check_admin_referer('ls_contact');$name=sanitize_text_field(wp_unslash($_POST['name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));if(!$name||!is_email($email)||!$message||empty($_POST['consent'])||ls_text_length($name)>100||ls_text_length($message)>2000)wp_die('Проверьте заполнение формы.', '',array('response'=>400));$ok=wp_mail(get_option('admin_email'),'Запись LinguaSpace',$name."\n".$email."\n".$message);wp_safe_redirect(add_query_arg('sent',$ok?'1':'0',home_url('/contacts/')));exit;}
add_shortcode('ls_contact',function(){ob_start();if(isset($_GET['sent']))echo '<p role="status">'.($_GET['sent']==='1'?'Заявка отправлена.':'Отправка не удалась. Повторите позже.').'</p>';?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="ls_contact"><?php wp_nonce_field('ls_contact'); ?><label>Имя<input name="name" required maxlength="100"></label><label>Электронная почта<input name="email" type="email" required></label><label>Ваш вопрос или интересующий курс<textarea name="message" required maxlength="2000"></textarea></label><label><input style="width:auto;display:inline" type="checkbox" name="consent" value="1" required> Согласен на обработку данных для ответа на обращение.</label><p><a href="<?php echo esc_url(home_url('/privacy/')); ?>">Обработка персональных данных</a></p><button>Отправить заявку</button></form><?php return ob_get_clean();});
add_shortcode('ls_articles',function(){ $q=new WP_Query(array('post_type'=>'post','posts_per_page'=>15,'post_status'=>'publish'));$s='<div class="cards article-grid">';while($q->have_posts()){$q->the_post();$cats=get_the_category();$s.='<article class="tile"><span class="section-label">'.esc_html($cats?$cats[0]->name:'Материалы').'</span><h2><a href="'.esc_url(get_permalink()).'">'.esc_html(get_the_title()).'</a></h2><p>'.esc_html(wp_trim_words(wp_strip_all_tags(get_the_excerpt()),24)).'</p><a class="read-more" href="'.esc_url(get_permalink()).'">Читать статью →</a></article>';}wp_reset_postdata();return $s.'</div>';});

add_filter("wp_robots", function($robots){if(is_search()){ $robots["noindex"]=true; unset($robots["index"]); } return $robots;});
